import {createViewer,setViewerConfig,PerspectiveCamera,BackgroundMode,Vector3,Color,SplatLoader,SplatUtils} from '../vendor/aholo/index.js';
import * as THREE from '../vendor/three.module.js';
const $=s=>document.querySelector(s);let m,mode='space',viewer,camera,splat,loading=false,loaded=false,panoRender,panoScene,panoCamera,panoReady=false;
let yaw=Math.PI,pitch=0,zUp=true,origin=[0,0,0],eye=[0,0,0],lastDraw=0;
const requested=new URLSearchParams(location.search).get('id');
function waiting(title,message){$('#waiting').hidden=false;$('#title').textContent=title;$('#message').textContent=message;}
async function poll(){try{const r=await fetch('/api/memories',{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const j=await r.json();$('#budget').textContent=`本轮 ${j.attempts} / ${j.limit} 次`;const worlds=j.items.filter(x=>x.mode==='world');m=requested?worlds.find(x=>x.id===requested):worlds.at(-1);const selection=$('#world-version');if(selection.options.length!==worlds.length){selection.replaceChildren(...worlds.map(x=>{const option=document.createElement('option');option.value=x.id;option.textContent=x.name;return option;}));}if(m)selection.value=m.id;if(!m){waiting('还没有空间记忆','此入口仅展示已生成的 World 空间。');return;}$('#reference').src=m.photo_url;$('#original').src=m.photo_url;$('#status').textContent=m.message;$('#details').textContent=m.world_id?`World ID：${m.world_id}`:'';const a=m.world_assets||{};$('#tab-pano').disabled=!a.panorama_url;if(a.splat_url){$('#download-splat').href=a.splat_url;$('#download-splat').hidden=false;}if(a.panorama_url){$('#download-pano').href=a.panorama_url;$('#download-pano').hidden=false;}if(m.status==='ready'){const duration=m.completed_at?Math.round(m.completed_at-m.created_at):null;if(duration)$('#details').textContent+=` · 耗时 ${Math.floor(duration/60)} 分 ${duration%60} 秒`;if(mode==='space'&&!loaded&&!loading)loadSpace();else if(mode==='pano'&&!panoReady)loadPano();return;}if(mode!=='original')waiting('空间正在展开',m.message);const sec=Math.floor(Date.now()/1000-m.created_at);$('#elapsed').textContent=`已等待 ${Math.floor(sec/60)} 分 ${sec%60} 秒 · 自动查询，不重新生成`;if(['failed','paused','uncertain'].includes(m.status))waiting('空间任务暂未完成',m.message);}catch{if(!loaded)waiting('正在重新连接','查询暂时中断，稍后继续获取已有任务，不会重新生成。');}finally{setTimeout(poll,12000);}}
function look(){if(!camera)return;camera.position.set(...eye);const c=Math.cos(pitch);const d=zUp?new Vector3(c*Math.cos(yaw),c*Math.sin(yaw),Math.sin(pitch)):new Vector3(c*Math.sin(yaw),Math.sin(pitch),-c*Math.cos(yaw));camera.lookAt(new Vector3(eye[0]+d.x,eye[1]+d.y,eye[2]+d.z));camera.updateMatrixWorld();viewer?.setCamera(camera);requestDraw();}
function requestDraw(){if(viewer&&mode==='space'&&!lastDraw)lastDraw=requestAnimationFrame(()=>{lastDraw=0;viewer.render();});}
function size(){if(viewer&&camera){const b=$('#space').getBoundingClientRect();camera.aspect=b.width/Math.max(b.height,1);camera.updateProjectionMatrix();viewer.resize();viewer.setCamera(camera);requestDraw();}if(panoRender&&panoCamera){const b=$('#pano').getBoundingClientRect();if(b.width&&b.height){panoRender.setSize(b.width,b.height);panoCamera.aspect=b.width/b.height;panoCamera.updateProjectionMatrix();drawPano();}}}
async function loadSpace(){loading=true;waiting('正在加载真实 3DGS','下载并解析 World 生成的空间资源…');try{const a=m.world_assets;viewer=createViewer('memory-world',$('#space'),{});camera=new PerspectiveCamera(65,1,.02,500);zUp=a.up_axis==='Z';camera.up.set(0,zUp?0:1,zUp?1:0);const r=await fetch(a.splat_url);if(!r.ok)throw Error('本地 3DGS 文件读取失败');const bytes=new Uint8Array(await r.arrayBuffer());const type=a.format==='spz'?SplatLoader.SplatFileType.SPZ:SplatLoader.SplatFileType.PLY;const data=await SplatLoader.parseSplatData(type,bytes,SplatLoader.SplatPackType.Compressed);splat=await SplatUtils.createSplat(data);viewer.getScene().add(splat);setViewerConfig(viewer,{pipeline:{Background:{background:{active:BackgroundMode.BasicBackground,basic:{color:new Color(.02,.035,.04)}},ground:{enabled:false}},Splatting:{enabled:true},TAA:{enabled:false}}});viewer.requestRenderHandler=requestDraw;eye=[...origin];look();size();loaded=true;$('#space').dataset.loaded='true';$('#waiting').hidden=mode!=='space'?$('#waiting').hidden:true;$('#controls').hidden=mode!=='space';$('#elapsed').textContent='';requestDraw();}catch(e){viewer?.destroy();viewer=null;waiting('3D 空间暂未打开',e.message||'资源已保存，可切到生成全景查看。');}finally{loading=false;}}
function drawPano(){if(!panoReady)return;const c=Math.cos(pitch);panoCamera.lookAt(c*Math.sin(yaw-Math.PI/2),Math.sin(pitch),-c*Math.cos(yaw-Math.PI/2));panoRender.render(panoScene,panoCamera);}
async function loadPano(){waiting('正在展开生成全景','这是空间生成的全景图，可环顾但不能改变拍摄位置。');try{panoRender=new THREE.WebGLRenderer({antialias:true});panoRender.setPixelRatio(Math.min(devicePixelRatio,1.5));$('#pano').append(panoRender.domElement);panoScene=new THREE.Scene();panoCamera=new THREE.PerspectiveCamera(65,1,.1,100);const texture=await new THREE.TextureLoader().loadAsync(m.world_assets.panorama_url);texture.colorSpace=THREE.SRGBColorSpace;const mesh=new THREE.Mesh(new THREE.SphereGeometry(20,64,32),new THREE.MeshBasicMaterial({map:texture,side:THREE.BackSide}));panoScene.add(mesh);panoReady=true;size();drawPano();$('#waiting').hidden=true;$('#controls').textContent='拖动环顾 · 全景图模式';$('#controls').hidden=false;}catch{waiting('全景暂未打开','可以下载本地全景文件查看。');}}
async function switchMode(next){mode=next;for(const n of ['space','pano','original']){$(`#${n}`).hidden=n!==mode;$(`#tab-${n}`).classList.toggle('active',n===mode);}$('#controls').hidden=true;if(mode==='original'){$('#waiting').hidden=true;return;}if(!m||m.status!=='ready'){waiting('空间正在展开',m?.message||'正在读取…');return;}if(mode==='space'){if(!loaded&&!loading)loadSpace();else if(loaded){$('#waiting').hidden=true;$('#controls').textContent='拖动环顾 · 滚轮微移 · 方向键微移（无碰撞）';$('#controls').hidden=false;size();requestDraw();}}else{if(!panoReady)loadPano();else{$('#waiting').hidden=true;$('#controls').textContent='拖动环顾 · 全景图模式';$('#controls').hidden=false;size();}}}
for(const n of ['space','pano','original'])$(`#tab-${n}`).onclick=()=>switchMode(n);
let dragging=false,prevX=0,prevY=0;for(const el of [$('#space'),$('#pano')]){el.addEventListener('pointerdown',e=>{dragging=true;prevX=e.clientX;prevY=e.clientY;el.setPointerCapture(e.pointerId);});el.addEventListener('pointerup',()=>dragging=false);el.addEventListener('pointercancel',()=>dragging=false);el.addEventListener('pointermove',e=>{if(!dragging)return;yaw-=(e.clientX-prevX)*.004;pitch=Math.max(-1.4,Math.min(1.4,pitch+(e.clientY-prevY)*.004));prevX=e.clientX;prevY=e.clientY;mode==='space'?look():drawPano();});el.addEventListener('wheel',e=>{e.preventDefault();if(mode!=='space'||!loaded)return;const step=Math.max(-.15,Math.min(.15,-e.deltaY*.001));const dir=zUp?[Math.cos(yaw),Math.sin(yaw),0]:[Math.sin(yaw),0,-Math.cos(yaw)];eye=eye.map((v,i)=>Math.max(origin[i]-1.5,Math.min(origin[i]+1.5,v+dir[i]*step)));look();},{passive:false});}
addEventListener('keydown',e=>{if(!loaded||mode!=='space'||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const forward=e.key==='ArrowUp'?.1:e.key==='ArrowDown'?-.1:0;const side=e.key==='ArrowLeft'?-.1:e.key==='ArrowRight'?.1:0;const a=zUp?[Math.cos(yaw)*forward-Math.sin(yaw)*side,Math.sin(yaw)*forward+Math.cos(yaw)*side,0]:[Math.sin(yaw)*forward+Math.cos(yaw)*side,0,-Math.cos(yaw)*forward+Math.sin(yaw)*side];eye=eye.map((v,i)=>Math.max(origin[i]-1.5,Math.min(origin[i]+1.5,v+a[i])));look();});
$('#reset').onclick=()=>{eye=[...origin];yaw=Math.PI;pitch=0;look();drawPano();};new ResizeObserver(size).observe($('#space'));addEventListener('resize',size);addEventListener('pagehide',()=>{viewer?.destroy();panoRender?.dispose();});poll();

$('#world-version').onchange=e=>{location.href='/world/?id='+encodeURIComponent(e.target.value);};
